"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, glassFill, primaryFill } from "./_shared";

/**
 * Ink mail IconButton: a single glyph in the same materials as the Button.
 *
 * The square shape takes a corner that grows with its size, so a small one
 * never reads as a circle; `corners="circle"` makes it round. The default is
 * a quiet ghost for toolbars and table rows. `primary` is the off-white
 * fill, kept for the one action a screen offers, and `glass` pairs with it.
 * Nothing casts a shadow.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    "transition-[background-color,background-image,color,border-color] duration-fast ease-out",
    focusRing,
    "disabled:pointer-events-none disabled:border-transparent disabled:bg-muted disabled:bg-none disabled:text-(--foreground-disabled)",
    "data-[disabled]:pointer-events-none data-[disabled]:border-transparent data-[disabled]:bg-muted data-[disabled]:bg-none data-[disabled]:text-(--foreground-disabled)",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default:
          "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
        primary: primaryFill,
        secondary:
          "border border-(--line-strong) bg-secondary text-secondary-foreground hover:bg-muted",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline:
          "border border-(--line-strong) bg-transparent text-foreground hover:bg-secondary",
        glass: glassFill,
      },
      size: {
        xs: "size-7 rounded-md [&_svg]:size-3.5",
        sm: "size-8 rounded-lg [&_svg]:size-4",
        default: "size-10 rounded-xl [&_svg]:size-4",
        lg: "size-12 rounded-xl [&_svg]:size-5",
        xl: "size-14 rounded-2xl [&_svg]:size-6",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "square",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
